import math
def info_nce(sims, pos=0, T=0.1):
    e = [math.exp(s / T) for s in sims]
    return -math.log(e[pos] / sum(e))
print(round(info_nce([0.30, 0.25, 0.20]), 3))  # 0.68
print(round(info_nce([0.70, 0.20, 0.10]), 3))  # 0.009

